const LEAGUES=[
  {id:58005,name:'LIGA FPL KK OLD BOYS'},
  {id:131997,name:'OVERALL IFE'}
];
const GW_LABELS={1:'GW1 · Opening Weekend',2:'GW2',3:'GW3',4:'GW4',5:'GW5',6:'GW6',7:'GW7',8:'GW8',9:'GW9',10:'GW10',11:'GW11',12:'GW12',13:'GW13',14:'GW14',15:'GW15',16:'GW16',17:'GW17',18:'GW18',19:'GW19',20:'GW20',21:'GW21',22:'GW22',23:'GW23',24:'GW24',25:'GW25',26:'GW26',27:'GW27',28:'GW28',29:'GW29',30:'GW30',31:'GW31',32:'GW32',33:'GW33',34:'GW34',35:'GW35',36:'GW36',37:'GW37',38:'GW38 · Finale'};
const state={league:58005,gw:null,liveGw:null,compact:null,full:null,available:{},sort:{key:'league_rank',dir:1},view:'overview',loaded:false,playerIndex:new Map(),teamIndex:new Map(),teamById:new Map(),fixtureIndex:new Map(),fdrIndex:new Map()};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const fmt=n=>new Intl.NumberFormat('en-MY').format(Number(n||0));
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const ago=d=>{const s=Math.floor((Date.now()-new Date(d).getTime())/1000);if(s<60)return'just now';if(s<3600)return`${Math.floor(s/60)}m ago`;if(s<86400)return`${Math.floor(s/3600)}h ago`;return`${Math.floor(s/86400)}d ago`};
const ELITE_THRESHOLD_PCT=5; // top 5% by overall_rank
const MY_TEAM_ID=2797967; // Muhd Irfan's FPL team; used as the default My Team view

const playerPhoto=p=>{const photo=state.playerIndex.get(Number(p?.id||p?.element))?.photo||'';return photo?`https://resources.premierleague.com/premierleague/photos/players/110x140/p${photo.replace(/\.(jpg|png)$/,'')}.png`:''};
const teamBadge=p=>{const team=state.teamIndex.get(String(p?.team||'').toLowerCase());return team?.code?`https://resources.premierleague.com/premierleague/badges/70/t${team.code}.png`:''};
const playerInitials=p=>String(p?.name||'').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'FC';
const playerImg=p=>{const src=playerPhoto(p),badge=teamBadge(p);return `<span class="player-avatar"><span class="player-fallback">${badge?`<img class="team-badge" src="${badge}" alt="${esc(p?.team||'')} badge" loading="lazy" onerror="this.remove()">`:''}<span>${playerInitials(p)}</span></span>${src?`<img class="player-thumb" src="${src}" alt="${esc(p?.name||'')}" loading="lazy" onerror="this.remove()">`:''}<span class="player-detail-meta">${playerDisplayMeta(p)}</span></span>`};
const startingXI=squad=>{const active=(squad||[]).filter(p=>Number(p.multiplier)>0);return active.length===11?active:(squad||[]).slice(0,11)};
async function getJson(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw new Error(`${r.status} ${path}`);return r.json()}
async function discover(){const a={};await Promise.all(LEAGUES.map(async l=>{const id=l.id;a[id]=[];for(let g=1;g<=5;g++){try{const r=await fetch(`/data/gw${g}_league${id}_compact.json`,{method:'HEAD',cache:'no-store'});if(r.ok)a[id].push(g);else break}catch{break}}}));return a}
const mean=x=>x.length?x.reduce((a,b)=>a+b,0)/x.length:0;const median=x=>{if(!x.length)return 0;const a=[...x].sort((p,q)=>p-q),m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2};
function captainCounts(rows){const m=new Map();rows.forEach(r=>m.set(r.captain||'N/A',(m.get(r.captain||'N/A')||0)+1));return[...m].sort((a,b)=>b[1]-a[1])}
function delta(r){const cur=+r.league_rank||0,prev=+r.league_last_rank||0;return prev&&cur?prev-cur:0}function deltaHtml(r){const d=delta(r);return d?`<span class="delta ${d>0?'up':'down'}">${d>0?'▲':'▼'} ${Math.abs(d)}</span>`:'<span class="delta flat">—</span>'}
function leagueName(id){const l=LEAGUES.find(x=>x.id===id);return l?l.name:`League ${id}`}

// ── Overview ──
function renderKpis(rows){const pts=rows.map(r=>+r.gw_points||0),top=[...rows].sort((a,b)=>(b.gw_points||0)-(a.gw_points||0))[0],hasBaseline=state.gw>1&&rows.some(r=>+r.league_last_rank>0),movers=rows.filter(r=>delta(r)>0).length;$('#kpis').innerHTML=[['Managers',fmt(rows.length),'selected league'],['Average GW',mean(pts).toFixed(1),`Median ${median(pts).toFixed(1)}`],['Top Score',fmt(top?.gw_points||0),top?.entry_name||'—'],['Rank Risers',hasBaseline?fmt(movers):'—',hasBaseline?'improved rank':'baseline week']].map(x=>`<div class="kpi"><span>${x[0]}</span><strong>${esc(x[1])}</strong><small>${esc(x[2])}</small></div>`).join('')}
function renderTop(rows){$('#topPerformers').innerHTML=[...rows].sort((a,b)=>(b.gw_points||0)-(a.gw_points||0)).slice(0,10).map((r,i)=>`<div class="rank-row manager-link" data-id="${r.entry_id}" style="animation-delay:${i*0.05}s"><div class="rank-num">${i+1}</div><div><strong>${esc(r.entry_name)}</strong><small>${esc(r.player_name)}</small></div><span>${fmt(r.gw_points)} pts</span></div>`).join('')}
function renderCaptains(rows){const caps=captainCounts(rows).slice(0,8),max=caps[0]?.[1]||1;$('#captainBars').innerHTML=caps.map(([n,c])=>`<div class="bar-row"><div class="bar-label">${esc(n)}</div><div class="bar-track"><div class="bar-fill" style="width:${c/max*100}%"></div></div><div class="bar-value">${(c/rows.length*100).toFixed(1)}%</div></div>`).join('')}
function renderDistribution(rows){const vals=rows.map(r=>+r.gw_points||0);if(!vals.length)return;const min=Math.min(...vals),max=Math.max(...vals),step=Math.max(5,Math.ceil((max-min||5)/12/5)*5),bins=[];for(let a=Math.floor(min/step)*step;a<=max;a+=step)bins.push({a,b:a+step-1,n:0});vals.forEach(v=>{const i=Math.min(bins.length-1,Math.floor((v-bins[0].a)/step));if(bins[i])bins[i].n++});const mx=Math.max(...bins.map(b=>b.n),1);$('#distribution').innerHTML=bins.map(b=>`<div class="hist-bar" style="height:${Math.max(4,b.n/mx*100)}%" data-count="${b.n}" data-label="${b.a}-${b.b}: ${b.n}"></div>`).join('');$('#distMeta').textContent=`${min}–${max} pts · hover a bar for range`}
function renderRankMovers(rows){const movers=[...rows].sort((a,b)=>Math.abs(delta(b))-Math.abs(delta(a))).slice(0,10);$('#rankMovers').innerHTML=movers.map(r=>`<div class="rank-row manager-link" data-id="${r.entry_id}"><div>${deltaHtml(r)}</div><div><strong>${esc(r.entry_name)}</strong><small>${esc(r.player_name)}</small></div><span>#${fmt(r.league_rank)}</span></div>`).join('')||'<div class="empty">No rank movement yet.</div>'}

// ── League Explorer ──
function filteredManagers(input){const q=input.trim().toLowerCase();return(state.compact?.competitors||[]).filter(r=>!q||`${r.entry_name} ${r.player_name}`.toLowerCase().includes(q))}
function renderLeague(){let rows=filteredManagers($('#leagueSearch').value);const{key,dir}=state.sort;rows.sort((a,b)=>{const x=a[key]??'',y=b[key]??'';return typeof x==='number'?(x-y)*dir:String(x).localeCompare(String(y))*dir});$('#leagueBody').innerHTML=rows.map(r=>`<tr data-id="${r.entry_id}"><td>${fmt(r.league_rank)}</td><td>${deltaHtml(r)}</td><td><strong>${esc(r.entry_name)}</strong></td><td>${esc(r.player_name)}</td><td>${fmt(r.gw_points)}</td><td>${fmt(r.total_points)}</td><td><span class="pill">${esc(r.captain)}</span></td><td>${fmt(r.transfers_made)}</td></tr>`).join('')}
function renderManagerCards(){const rows=filteredManagers($('#managerSearch').value).sort((a,b)=>(a.league_rank||99999)-(b.league_rank||99999)).slice(0,300);$('#managerCards').innerHTML=rows.map(r=>`<div class="manager-card" data-id="${r.entry_id}"><div class="manager-card-top"><span class="manager-rank">#${fmt(r.league_rank)}</span><strong>${fmt(r.gw_points)} pts</strong></div><h3>${esc(r.entry_name)}</h3><span class="manager-owner">${esc(r.player_name)}</span><div class="manager-meta"><small>Captain</small><b>${esc(r.captain)}</b></div></div>`).join('')}

// ── Data helpers ──
async function ensureFull(){if(state.full)return state.full;state.full=await getJson(`/data/gw${state.gw}_league${state.league}_data.json`);return state.full}
function playerMap(rows){const m=new Map();rows.forEach(c=>(c.squad||[]).forEach(p=>{const x=m.get(p.element)||{id:p.element,element:p.element,name:p.name,team:p.team,position:p.position,owned:0,captain:0,vc:0,squad_cost:0,selected_by:p.selected_by||0,form:0,formN:0};x.owned++;if(p.is_captain)x.captain++;if(p.is_vice_captain)x.vc++;x.squad_cost+=p.cost||0;const indexed=state.playerIndex.get(Number(p.element));if(indexed&&Number.isFinite(+indexed.form)){x.form+=+indexed.form;x.formN++}m.set(p.element,x)}));return m}

// ── Template XI ──
async function renderTemplate(){try{const rows=(await ensureFull()).competitors||[],arr=[...playerMap(rows).values()].sort((a,b)=>b.owned-a.owned);const byPos=p=>arr.filter(x=>x.position===p);const XI=[...byPos('GKP').slice(0,1),...byPos('DEF').slice(0,3),...byPos('MID').slice(0,4),...byPos('FWD').slice(0,3)];$('#templateXI').innerHTML=XI.map(p=>`<div class="template-card">${playerImg(p)}<div><strong>${esc(p.name)}</strong><span>${esc(p.position)} · ${esc(p.team)}</span><small>${(p.owned/rows.length*100).toFixed(1)}% owned</small></div></div>`).join('')}catch{$('#templateXI').innerHTML='<div class="empty">Full snapshot unavailable.</div>'}}

// ── Player Intelligence ──
async function renderPlayers(){try{const rows=(await ensureFull()).competitors||[],q=$('#playerSearch').value.trim().toLowerCase(),arr=[...playerMap(rows).values()].filter(p=>!q||`${p.name} ${p.team}`.toLowerCase().includes(q)).sort((a,b)=>b.owned-a.owned);$('#playerBody').innerHTML=arr.map(p=>{const own=p.owned/rows.length*100,diff=own<10?'High':own<25?'Medium':'Template';return`<tr><td><div class="player-cell">${playerImg(p)}<strong>${esc(p.name)}</strong></div></td><td>${esc(p.team)}</td><td>${esc(p.position)}</td><td>${p.owned}</td><td>${own.toFixed(1)}%</td><td>${p.captain}</td><td>${(p.captain/rows.length*100).toFixed(1)}%</td><td><span class="pill">${diff}</span></td><td>${p.formN?(p.form/p.formN).toFixed(1):'—'}</td></tr>`}).join('');$('#playerLoading').textContent=''}catch(e){$('#playerLoading').textContent=`Could not load full snapshot: ${e.message}`}}

// ── Manager Selects ──
function managerOptions(rows){return rows.map(r=>`<option value="${r.entry_id}">#${r.league_rank} ${esc(r.entry_name)} — ${esc(r.player_name)}</option>`).join('')}
function populateManagerSelects(){const rows=[...(state.compact?.competitors||[])].sort((a,b)=>(a.league_rank||99999)-(b.league_rank||99999));state.managerRows=rows;const opts=managerOptions(rows);['compareA','compareB','myTeamSelect'].forEach(id=>$('#'+id).innerHTML=opts);if(rows[1])$('#compareB').value=rows[1].entry_id;const mine=rows.find(r=>String(r.entry_id)===String(MY_TEAM_ID));if(mine)$('#myTeamSelect').value=String(MY_TEAM_ID)}
function filterManagerSelect(selectId,searchId){const q=$('#'+searchId).value.trim().toLowerCase();const rows=(state.managerRows||[]).filter(r=>!q||`${r.entry_name} ${r.player_name}`.toLowerCase().includes(q));const previous=$('#'+selectId).value;$('#'+selectId).innerHTML=managerOptions(rows);if(rows.some(r=>String(r.entry_id)===String(previous)))$('#'+selectId).value=previous;else if(rows[0])$('#'+selectId).value=rows[0].entry_id;renderCompare()}

// ── Compare Managers ──
async function renderCompare(){try{const rows=(await ensureFull()).competitors||[],a=rows.find(x=>String(x.entry_id)===$('#compareA').value),b=rows.find(x=>String(x.entry_id)===$('#compareB').value);if(!a||!b)return;const sa=new Map((a.squad||[]).map(p=>[p.element,p])),sb=new Map((b.squad||[]).map(p=>[p.element,p]));const common=[...sa.keys()].filter(k=>sb.has(k)),ua=[...sa.values()].filter(p=>!sb.has(p.element)),ub=[...sb.values()].filter(p=>!sa.has(p.element));$('#compareResult').innerHTML=`<div class="mini-kpis"><div class="mini-kpi"><span>Squad overlap</span><strong>${common.length}/15</strong></div><div class="mini-kpi"><span>${esc(a.entry_name)} unique</span><strong>${ua.length}</strong></div><div class="mini-kpi"><span>${esc(b.entry_name)} unique</span><strong>${ub.length}</strong></div><div class="mini-kpi"><span>GW points gap</span><strong>${Math.abs((a.gw_points||0)-(b.gw_points||0))}</strong></div></div><div class="compare-grid"><div><h3>${esc(a.entry_name)}</h3>${ua.map(p=>`<span class="pick-chip">${esc(p.name)}</span>`).join('')||'No unique picks'}</div><div><h3>Shared ${common.length}</h3>${common.map(id=>`<span class="pick-chip shared">${esc(sa.get(id).name)}</span>`).join('')}</div><div><h3>${esc(b.entry_name)}</h3>${ub.map(p=>`<span class="pick-chip">${esc(p.name)}</span>`).join('')||'No unique picks'}</div></div>`}catch(e){$('#compareResult').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}

// ── Transfers & Chips ──
async function renderTransfers(){try{const rows=(await ensureFull()).competitors||[],moves=new Map(),chips=new Map();rows.forEach(c=>{(c.transfer_details||[]).forEach(t=>{const k=`${t.out} → ${t.in}`;moves.set(k,(moves.get(k)||0)+1)});(c.chips_used||[]).forEach(ch=>{const n=ch.name||ch.chip_name||'Chip';chips.set(n,(chips.get(n)||0)+1)})});$('#transferIntel').innerHTML=[...moves].sort((a,b)=>b[1]-a[1]).slice(0,15).map(([m,n])=>`<div class="rank-row"><div class="rank-num">${n}</div><div><strong>${esc(m)}</strong></div><span>${n} moves</span></div>`).join('')||'<div class="empty">No recorded transfers for this GW.</div>';$('#chipTracker').innerHTML=[...chips].sort((a,b)=>b[1]-a[1]).map(([n,c])=>`<div class="rank-row"><div class="rank-num">${c}</div><div><strong>${esc(n)}</strong></div><span>${c} used</span></div>`).join('')||'<div class="empty">No chips used this GW.</div>';renderChipChart(chips,rows.length)}catch(e){$('#transferIntel').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderChipChart(chips,total){const entries=[...chips];if(!entries.length){$('#chipChart').innerHTML='';return}const colors={'bboost':'#43d986','3xc':'#68e7ff','wildcard':'#ffd166','freehit':'#ff7d87','Bench Boost':'#43d986','Triple Captain':'#68e7ff','Wildcard':'#ffd166','Free Hit':'#ff7d87'};$('#chipChart').innerHTML=`<div class="pie-legend">${entries.map(([n,c])=>`<span class="pie-legend-item"><span class="pie-dot" style="background:${colors[n]||'#80ffb2'}"></span>${esc(n)}: ${c} (${(c/total*100).toFixed(1)}%)</span>`).join('')}</div><div class="pie-track"><div class="pie-fills">${entries.map(([n,c],i)=>{const pct=c/total*100;const colorsArr=Object.values(colors);return`<div class="pie-seg" style="width:${pct}%;background:${colors[n]||colorsArr[i%colorsArr.length]};min-width:${pct>1?'4px':'0'}"></div>`}).join('')}</div></div>`}

// ── My Team ──
async function renderMyTeam(){
  try{
    const rows=(await ensureFull()).competitors||[], me=rows.find(x=>String(x.entry_id)===$('#myTeamSelect').value)||rows[0];
    if(!me)return;
    const pm=playerMap(rows), squad=me.squad||[], xi=startingXI(squad), bench=squad.filter(p=>!xi.includes(p));
    const byPos=pos=>xi.filter(p=>String(p.position||'').toUpperCase()===pos);
    const eliteCount=Math.max(1,Math.ceil(rows.length*ELITE_THRESHOLD_PCT/100)), elite=[...rows].sort((a,b)=>(a.overall_rank||a.league_rank||999999)-(b.overall_rank||b.league_rank||999999)).slice(0,eliteCount);
    const eliteIds=new Set(elite.flatMap(x=>x.squad||[]).map(p=>p.element));
    const overlap=squad.filter(p=>eliteIds.has(p.element)).length;
    const captain=xi.find(p=>p.is_captain)||squad.find(p=>p.name===me.captain);
    const playerCard=p=>{const own=((pm.get(p.element)?.owned||0)/rows.length*100).toFixed(1);return `<button class="myteam-player" data-player-id="${esc(p.element)}" type="button">${playerImg(p)}<strong>${esc(p.name)}</strong><span class="myteam-player-meta">${esc(playerDisplayMeta(p))}</span><small>${esc(p.team||'')} · ${esc(p.position||'')}</small>${p.is_captain?'<i class="myteam-badge">C</i>':''}${p.is_vice_captain?'<i class="myteam-badge">V</i>':''}<em>${own}% owned</em></button>`};
    const listRow=p=>`<tr><td><div class="myteam-list-player">${playerImg(p)}<strong>${esc(p.name)}</strong></div></td><td>${esc(p.position||'—')}</td><td>${esc(p.team||'—')}</td><td><strong>${esc(playerDisplayMeta(p))}</strong></td><td>${p.cost!=null?`£${Number(p.cost).toFixed(1)}m`:'—'}</td><td>${((pm.get(p.element)?.owned||0)/rows.length*100).toFixed(1)}%</td><td>${state.playerIndex.get(Number(p.element))?.form||'—'}</td></tr>`;
    $('#myTeamResult').innerHTML=`<section class="myteam-shell">
      <div class="myteam-hero"><div><span class="panel-kicker">MY TEAM · FPL SNAPSHOT</span><h2>${esc(me.entry_name)}</h2><p>${esc(me.player_name)} · League rank #${fmt(me.league_rank)} · GW${state.gw}</p></div><div class="myteam-source">Selected league snapshot<span>GCP Autopilot bridge pending</span></div></div>
      <div class="myteam-toolbar"><div><span class="panel-kicker">GAMEWEEK ${state.gw}</span><h2>My Team</h2><p>Starting XI, bench, captaincy and next fixture context.</p></div><div class="myteam-actions"><button id="myTeamPitchBtn" class="myteam-tab active" type="button">Pitch</button><button id="myTeamListBtn" class="myteam-tab" type="button">List</button></div></div>
      <div class="myteam-kpis"><div><span>GW points</span><strong>${fmt(me.gw_points)}</strong></div><div><span>Total points</span><strong>${fmt(me.total_points)}</strong></div><div><span>League rank</span><strong>#${fmt(me.league_rank)}</strong></div><div><span>Squad value</span><strong>£${Number(me.squad_value||0).toFixed(1)}m</strong></div></div>
      <div class="myteam-pitch-view"><div class="myteam-pitch-head"><div><span class="panel-kicker">STARTING XI</span><strong>${xi.length}/11 players</strong></div><span>${esc(GW_LABELS[state.gw]||`GW${state.gw}`)}</span></div><div class="myteam-pitch"><div class="myteam-pitch-row goalkeeper">${byPos('GKP').map(playerCard).join('')}</div><div class="myteam-pitch-row defenders">${byPos('DEF').map(playerCard).join('')}</div><div class="myteam-pitch-row midfielders">${byPos('MID').map(playerCard).join('')}</div><div class="myteam-pitch-row forwards">${byPos('FWD').map(playerCard).join('')}</div></div><div class="myteam-bench-head"><span class="panel-kicker">BENCH</span><span>${bench.length}/4 substitutes</span></div><div class="myteam-bench">${bench.map(p=>`<div class="myteam-bench-player">${playerImg(p)}<div><strong>${esc(p.name)}</strong><small>${esc(p.team||'')} · ${esc(p.position||'')}</small><b>${esc(playerDisplayMeta(p))}</b></div></div>`).join('')}</div></div>
      <div class="myteam-list-view" hidden><div class="table-wrap"><table><thead><tr><th>Player</th><th>Position</th><th>Team</th><th>GW / fixture</th><th>Price</th><th>Ownership</th><th>Form</th></tr></thead><tbody>${[...xi,...bench].map(listRow).join('')}</tbody></table></div></div>
      <div class="myteam-context"><div><span class="panel-kicker">ELITE CONTEXT</span><h3>How close are you to the elite template?</h3><p>${overlap} of ${squad.length} squad players overlap with the top ${ELITE_THRESHOLD_PCT}% cohort. Captain: <strong>${esc(captain?.name||me.captain||'—')}</strong>.</p></div><button class="button" data-view="assistant" type="button">Open catch-up plan →</button></div>
    </section>`;
    const pitch=$('.myteam-pitch-view'), list=$('.myteam-list-view'), toggle=mode=>{const isPitch=mode==='pitch';pitch.hidden=!isPitch;list.hidden=isPitch;$('#myTeamPitchBtn').classList.toggle('active',isPitch);$('#myTeamListBtn').classList.toggle('active',!isPitch)};
    $('#myTeamPitchBtn').addEventListener('click',()=>toggle('pitch'));$('#myTeamListBtn').addEventListener('click',()=>toggle('list'));$('.myteam-context [data-view="assistant"]')?.addEventListener('click',()=>$('#nav [data-view="assistant"]')?.click());
  }catch(e){$('#myTeamResult').innerHTML=`<div class="empty">My Team unavailable: ${esc(e.message)}</div>`}
}

