const eliteTemplate=buildEliteTemplate(elite,rows,pm);eliteTemplate.eliteCount=eliteCount;eliteTemplate.starterPoints=eliteTemplate.starters.reduce((sum,p)=>sum+(Number(playerEventPoints(p))||0),0);eliteTemplate.captainCount=eliteTemplate.starters.filter(p=>p.is_captain).length;

