function playerUniverse(rows){
  const pm=playerMap(rows),pos={1:'GKP',2:'DEF',3:'MID',4:'FWD'};
  state.playerIndex.forEach(i=>{if(pm.has(i.id))return;pm.set(i.id,{id:i.id,element:i.id,name:i.web_name||`${i.first_name||''} ${i.second_name||''}`.trim(),team:state.teamById.get(Number(i.team))?.name||`Team ${i.team||'—'}`,position:pos[i.element_type]||'—',owned:0,captain:0,vc:0,squad_cost:0,selected_by:0,form:0,formN:0})});
  return pm;
}
function playerMetric(p,rows){
  const i=state.playerIndex.get(Number(p.element))||{};
  const own=p.owned/Math.max(rows.length,1)*100;
  const cap=p.captain/Math.max(rows.length,1)*100;
  return {...i,own,cap,eo:own+cap,ep:Number(i.ep_next||0),form:Number(i.form||0),price:Number(i.now_cost||0)/10,fdr:playerFdr(p),risk:i.status&&i.status!=='a'?'Risk':Number(i.chance_of_playing||100)<75?'Risk':'Ready'};
}
async function renderPlayers(){
  try{
    const rows=(await ensureFull()).competitors||[];
    const q=$('#playerSearch').value.trim().toLowerCase();
    const arr=[...playerUniverse(rows).values()].map(p=>({...p,...playerMetric(p,rows)})).filter(p=>!q||`${p.name} ${p.team}`.toLowerCase().includes(q)).sort((a,b)=>b.owned-a.owned);
    $('#playerBody').innerHTML=arr.map(p=>`<tr><td><div class="player-cell">${playerImg(p)}<strong>${esc(p.name)}</strong></div></td><td>${esc(p.team)}</td><td>${esc(p.position)}</td><td>£${p.price.toFixed(1)}m</td><td><strong>${p.ep.toFixed(1)}</strong> <small>${playerEventPoints(p)??'—'}</small></td><td>${esc(playerFixture(p))}</td><td><span class="fdr fdr-${p.fdr||0}">${p.fdr||'—'}</span></td><td><strong>${p.eo.toFixed(1)}%</strong></td><td>${p.own.toFixed(1)}%</td><td>${p.form.toFixed(1)}</td><td><span class="status-pill ${p.risk==='Ready'?'ready':'risk'}">${esc(p.news||p.risk)}</span></td></tr>`).join('')||'<tr><td colspan="11"><div class="empty">No players found.</div></td></tr>';
    $('#playerLoading').textContent=`${arr.length} players · EO = ownership + captaincy · xPts is the current FPL projection`;
    const compare=arr.slice(0,2);
    $('#playerComparePanel').innerHTML=compare.length===2?`<article class="panel player-compare"><div class="panel-head"><div><span class="panel-kicker">PLAYER COMPARISON</span><h2>${esc(compare[0].name)} vs ${esc(compare[1].name)}</h2><p>Quick decision view using projections, fixtures, form and effective ownership.</p></div><span class="panel-tag">MODEL SNAPSHOT</span></div><div class="player-compare-grid">${compare.map(p=>`<div class="player-compare-card">${playerImg(p)}<h3>${esc(p.name)}</h3><span>${esc(p.position)} · ${esc(p.team)}</span><b>${p.ep.toFixed(1)} xPts next GW</b><small>Form ${p.form.toFixed(1)} · £${p.price.toFixed(1)}m · EO ${p.eo.toFixed(1)}%</small><em>${esc(playerFixture(p))} · FDR ${p.fdr||'—'}</em></div>`).join('')}</div></article>`:'';
  }catch(e){$('#playerLoading').textContent=`Could not load full snapshot: ${esc(e.message)}`}
}
async function renderTransfers(){
  try{
    const rows=(await ensureFull()).competitors||[],moves=new Map(),chips=new Map();
    rows.forEach(c=>{(c.transfer_details||[]).forEach(t=>{const k=`${t.out} → ${t.in}`;moves.set(k,(moves.get(k)||0)+1)});(c.chips_used||[]).forEach(ch=>{const n=ch.name||ch.chip_name||'Chip';chips.set(n,(chips.get(n)||0)+1)})});
    $('#transferIntel').innerHTML=[...moves].sort((a,b)=>b[1]-a[1]).slice(0,15).map(([m,n])=>`<div class="rank-row"><div class="rank-num">${n}</div><div><strong>${esc(m)}</strong></div><span>${n} moves</span></div>`).join('')||'<div class="empty">No recorded transfers for this GW.</div>';
    $('#chipTracker').innerHTML=[...chips].sort((a,b)=>b[1]-a[1]).map(([n,c])=>`<div class="rank-row"><div class="rank-num">${c}</div><div><strong>${esc(n)}</strong></div><span>${c} used</span></div>`).join('')||'<div class="empty">No chips used this GW.</div>';
    renderChipChart(chips,rows.length);
    const me=rows.find(x=>String(x.entry_id)===$('#myTeamSelect').value)||rows[0];
    const elite=[...rows].sort((a,b)=>(a.overall_rank||99999999)-(b.overall_rank||99999999)).slice(0,Math.max(1,Math.ceil(rows.length*ELITE_THRESHOLD_PCT/100)));
    const mine=new Set((me?.squad||[]).map(p=>p.element)),owned=new Map();
    elite.forEach(c=>(c.squad||[]).forEach(p=>owned.set(p.element,(owned.get(p.element)||0)+1)));
    const pm=playerMap(rows),targets=[...pm.values()].map(p=>({...p,...playerMetric(p,rows),elitePct:(owned.get(p.element)||0)/elite.length*100})).filter(p=>!mine.has(p.element)&&p.elitePct>=20&&p.risk==='Ready').sort((a,b)=>(b.ep*.55+b.form*.15+b.elitePct*.3)-(a.ep*.55+a.form*.15+a.elitePct*.3)).slice(0,5),outs=(me?.squad||[]).map(p=>({...p,...playerMetric(p,rows)})).sort((a,b)=>(a.ep*.55+a.form*.15)-(b.ep*.55+b.form*.15)).slice(0,5);
    $('#transferPlanner').innerHTML=`<article class="panel transfer-plan"><div class="panel-head"><div><span class="panel-kicker">CATCH-UP PLANNER</span><h2>Recommended transfer shortlist</h2><p>Elite consensus + xPoints + form, filtered for availability. Review before sending to GCP Autopilot.</p></div><span class="panel-tag">NO AUTO-EXECUTION</span></div><div class="transfer-plan-grid">${targets.map((p,i)=>{const out=outs[i%Math.max(outs.length,1)];return`<div class="transfer-recommendation"><div><strong>${esc(out?.name||'Squad review')} → ${esc(p.name)}</strong><small>${esc(p.position)} · ${esc(p.team)} · ${esc(playerFixture(p))}</small></div><span>+${(p.ep-(out?.ep||0)).toFixed(1)} xPts</span><em>${p.elitePct.toFixed(1)}% elite · FDR ${p.fdr||'—'}</em></div>`}).join('')||'<div class="empty">No safe elite-alignment transfer found in this snapshot.</div>'}</div></article>`;
  }catch(e){$('#transferIntel').innerHTML=`<div class="empty">Transfer intelligence unavailable: ${esc(e.message)}</div>`}
}
async function renderAnalytics(){
  try{
    const rows=(await ensureFull()).competitors||[],pm=playerMap(rows),ranked=[...pm.values()].map(p=>{const m=playerMetric(p,rows);return{...p,...m,model:m.ep*.55+m.form*.15+m.own*.1+(m.risk==='Ready'?2:0)}}).sort((a,b)=>b.model-a.model),me=rows.find(x=>String(x.entry_id)===$('#myTeamSelect').value)||rows[0],elite=[...rows].sort((a,b)=>(a.overall_rank||99999999)-(b.overall_rank||99999999)).slice(0,Math.max(1,Math.ceil(rows.length*ELITE_THRESHOLD_PCT/100))),eliteAvg=mean(elite.map(x=>+x.gw_points||0)),actual=ranked.filter(p=>Number.isFinite(Number(p.event_points))),mae=actual.length?mean(actual.map(p=>Math.abs(p.ep-Number(p.event_points)))):null;
    $('#analyticsContent').innerHTML=`<div class="hero-strip" style="margin-bottom:16px"><div><span class="hero-kicker">MODEL LAB</span><h2>Decision quality and rank gap</h2><p>Transparent signals for xPoints, form, availability, ownership and elite alignment.</p></div></div><div class="mini-kpis"><div class="mini-kpi"><span>Your GW points</span><strong>${fmt(me?.gw_points)}</strong></div><div class="mini-kpi"><span>Elite average</span><strong>${eliteAvg.toFixed(1)}</strong></div><div class="mini-kpi"><span>Gap to elite</span><strong>${(Number(me?.gw_points||0)-eliteAvg).toFixed(1)}</strong></div><div class="mini-kpi"><span>xPts MAE</span><strong>${mae===null?'Pending':mae.toFixed(1)}</strong></div></div><div class="grid two"><article class="panel"><div class="panel-head"><div><span class="panel-kicker">MODEL RANKING</span><h2>Best next-GW signals</h2><p>Shortlist only; recommendations still require review.</p></div><span class="panel-tag">xPTS + FORM + EO</span></div>${ranked.slice(0,12).map((p,i)=>`<div class="rank-row"><div class="rank-num">${i+1}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.position)} · ${esc(p.team)} · ${p.ep.toFixed(1)} xPts · ${esc(playerFixture(p))}</small></div><span>${p.model.toFixed(1)}</span></div>`).join('')}</article><article class="panel"><div class="panel-head"><div><span class="panel-kicker">MODEL SCORECARD</span><h2>Can we trust the signal?</h2></div><span class="panel-tag">BACKTEST READY</span></div><div class="model-scorecard"><div><b>Inputs</b><span>xPts · form · ownership · FDR · availability · elite edge</span></div><div><b>Current validation</b><span>${actual.length?`${actual.length} players evaluated · MAE ${mae.toFixed(1)} points`:'Awaiting completed GW points'}</span></div><div><b>Execution</b><span>Recommendations require your review and Telegram approval.</span></div><div><b>Risk control</b><span>Template shields first; differentials are capped and availability-filtered.</span></div></div></article></div><article class="panel"><div class="panel-head"><div><span class="panel-kicker">FORMATION DISTRIBUTION</span><h2>What the league is actually starting</h2></div><span class="panel-tag">11 PLAYERS ONLY</span></div><div class="formation-list">${formationChart(rows)}</div></article>`;
  }catch(e){$('#analyticsContent').innerHTML=`<div class="empty">Analytics unavailable: ${esc(e.message)}</div>`}
}

// ── Load ──
async function load(){state.full=null;const lname=leagueName(state.league);$('#statusText').textContent=`Loading ${lname} · GW${state.gw}`;$('#pageTitle').textContent=`${lname} · GW${state.gw}`;try{state.compact=await getJson(`/data/gw${state.gw}_league${state.league}_compact.json`);const rows=state.compact.competitors||[];renderKpis(rows);renderTop(rows);renderCaptains(rows);renderDistribution(rows);renderRankMovers(rows);renderLeague();renderManagerCards();populateManagerSelects();$('#playerBody').innerHTML='';$('#playerLoading').textContent='Open this tab to derive player intelligence from the full GW snapshot.';$('#templateXI').innerHTML='<div class="empty">Loading template…</div>';renderTemplate();const fetched=state.compact.fetched_at?new Date(state.compact.fetched_at):null;$('#statusText').innerHTML=`${lname} · GW${state.gw} · ${fmt(rows.length)} managers ${fetched?`<span class="freshness-badge">${ago(fetched)}</span>`:''}`;if(state.view==='compare')renderCompare();if(state.view==='transfers')renderTransfers();if(state.view==='myteam')renderMyTeam();if(state.view==='assistant')renderAssistant();if(state.view==='elite')renderElite();if(state.view==='analytics')renderAnalytics()}catch(e){$('#statusText').textContent=`Dataset unavailable: ${e.message}`}}

async function loadTeamIndex(){try{const bootstrap=await getJson('/data/bootstrap_cache.json');state.liveGw=Number((bootstrap.events||[]).find(e=>e.is_current)?.id||(bootstrap.events||[]).find(e=>!e.finished)?.id||0);(bootstrap.teams||[]).forEach(t=>{state.teamIndex.set(String(t.name||'').toLowerCase(),t);state.teamById.set(Number(t.id),t)})}catch(e){console.warn('Team badge data unavailable',e)}}
loadTeamIndex();
async function loadFixtureIndex(){for(let g=1;g<=38;g++){try{const payload=await getJson(`/data/gw${g}_fixtures.json`),fixtures=payload[`gw${g}`]||[];fixtures.forEach(f=>{const home=String(f.team_h||'').toLowerCase(),away=String(f.team_a||'').toLowerCase();if(home&&away){state.fixtureIndex.set(`${g}|${home}`,`${f.team_a} (H)`);state.fixtureIndex.set(`${g}|${away}`,`${f.team_h} (A)`);state.fdrIndex.set(`${g}|${home}`,Number(f.team_h_difficulty||0));state.fdrIndex.set(`${g}|${away}`,Number(f.team_a_difficulty||0))}})}catch{if(g>2)break}}}
loadFixtureIndex();

function setupLeagueButtons(){const box=$('#leagueSelect');if(!box)return;box.innerHTML=LEAGUES.map(l=>`<button type="button" class="league-choice ${state.league===l.id?'active':''}" data-league="${l.id}">${esc(l.name)}</button>`).join('');box.querySelectorAll('.league-choice').forEach(b=>b.addEventListener('click',()=>{const id=Number(b.dataset.league);if(id===state.league)return;state.league=id;box.querySelectorAll('.league-choice').forEach(x=>x.classList.toggle('active',Number(x.dataset.league)===id));const g=state.available[state.league]||[];$('#gwSelect').innerHTML=g.map(x=>`<option value="${x}">${GW_LABELS[x]||`GW${x}`}</option>`).join('');state.gw=g[g.length-1]||1;$('#gwSelect').value=state.gw;load()}))}

// ── Init ──
async function init(){try{const bootstrap=await getJson('/data/bootstrap_cache.json');(bootstrap.elements||[]).forEach(p=>state.playerIndex.set(Number(p.id),p))}catch(e){console.warn('Player image/form data unavailable',e)}state.available=await discover();const ls=$('#leagueSelect');ls.innerHTML=LEAGUES.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('');if(!state.available[state.league]?.length)state.league=LEAGUES.find(l=>state.available[l.id]?.length)?.id||LEAGUES[0].id;ls.value=state.league;const sync=()=>{const g=state.available[state.league]||[];$('#gwSelect').innerHTML=g.map(x=>`<option value="${x}">${GW_LABELS[x]||`GW${x}`}</option>`).join('');state.gw=g[g.length-1]||1;$('#gwSelect').value=state.gw};sync();ls.addEventListener('change',()=>{state.league=+ls.value;sync();load()});$('#gwSelect').addEventListener('change',()=>{state.gw=+$('#gwSelect').value;load()});await load()}

