$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;$$('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.view').forEach(x=>x.classList.remove('active'));$(`#${b.dataset.view}`).classList.add('active');state.view=b.dataset.view;$('#pageTitle').textContent=b.textContent;if(state.view==='players')renderPlayers();if(state.view==='compare')renderCompare();if(state.view==='transfers')renderTransfers();if(state.view==='myteam')renderMyTeam();if(state.view==='assistant')renderAssistant();if(state.view==='elite')renderElite();if(state.view==='analytics')renderAnalytics()});
$('#leagueSearch').addEventListener('input',renderLeague);$('#managerSearch').addEventListener('input',renderManagerCards);$('#playerSearch').addEventListener('input',renderPlayers);$('#compareA').addEventListener('change',renderCompare);$('#compareB').addEventListener('change',renderCompare);$('#myTeamSelect').addEventListener('change',()=>{renderMyTeam();if(state.view==='assistant')renderAssistant()});document.addEventListener('click',e=>{const x=e.target.closest('[data-id]');if(x&&(x.closest('#leagueBody')||x.classList.contains('manager-card')||x.classList.contains('manager-link')||x.closest('.elite-manager-list')))openManager(x.dataset.id)});$$('th[data-sort]').forEach(th=>th.addEventListener('click',()=>{const k=th.dataset.sort;if(state.sort.key===k)state.sort.dir*=-1;else state.sort={key:k,dir:1};renderLeague()}));$('#closeDialog').addEventListener('click',()=>$('#managerDialog').close());init().then(setupLeagueButtons);setInterval(()=>{if(state.gw!==null)load()},15*60*1000);
